3	import { useActionState, useEffect, useState, useTransition } from "react";
4	import {
5	  deleteFreeMinecraftServer,
6	  startFreeMinecraftServer,
7	  stopFreeMinecraftServer,
8	  restartFreeMinecraftServer,
9	  renameFreeMinecraftServer,
10	  changeFreeMinecraftSubdomain,
11	  sendFreeMinecraftCommand,
12	  getFreeMinecraftPlayers,
13	  applyFreeMinecraftSettings,
14	} from "@/lib/actions-free-minecraft";
15	import { PublicListingCard } from "./PublicListingCard";
16	import { InventoryEditor } from "./InventoryEditor";
17	import { ModsTab } from "./ModsTab";
18	import { RolesTab } from "./RolesTab";
19	import { OverviewRedesigned, FreeMcTopCardHero } from "./OverviewRedesigned";
20	import type { FreeMcGameType } from "./GameTypeGrid";
21	import type { FreeMcGameMode } from "./GameModeSelector";
22	
23	type Server = {
24	  id: string;
25	  subdomain: string;
26	  name: string | null;
27	  preset: string;
28	  activeGameType: string;
29	  activeGameMode: string;
30	  running: boolean;
31	  players: { online: number; max: number } | null;
32	  isPublic: boolean;
33	  publicTagline: string | null;
34	  publicDescription: string | null;
35	  extraMods: string[];
36	};
37	
38	type Field = {
39	  key: string;
40	  label: string;
41	  group: string;
42	  type: "enum" | "bool" | "int" | "string";
43	  default: string | number | boolean;
44	  options?: { value: string; label: string }[];
45	  min?: number;
46	  max?: number;
47	  phase: "deploy" | "live";
48	  help?: string;
49	};
50	
51	type Preset = {
52	  label: string;
53	  description: string;
54	  kind: "properties" | "plugins";
55	  properties: Record<string, string>;
56	  setupNote?: string;
57	  heroImage?: string;
58	};
59	
60	const TABS = [
61	  { key: "overview", label: "Overview" },
62	  { key: "console", label: "Console" },
63	  { key: "players", label: "Players" },
64	  { key: "mods", label: "Mods" },
65	  { key: "roles", label: "Roles" },
66	  { key: "settings", label: "Settings" },
67	  { key: "manage", label: "Manage" },
68	] as const;
69	type TabKey = (typeof TABS)[number]["key"];
70	
71	export function FreeMcDashboard({
72	  server,
73	  domain,
74	  schemaFields,
75	  properties,
76	  presets,
77	  gameTypes,
78	  gameModes,
79	}: {
80	  server: Server;
81	  domain: string;
82	  schemaFields: Field[];
83	  properties: Record<string, string>;
84	  presets: Record<string, Preset>;
85	  gameTypes: Record<string, FreeMcGameType>;
86	  gameModes: Record<string, FreeMcGameMode>;
87	}) {
88	  const [tab, setTab] = useState<TabKey>("overview");
