96	          <div className="flex items-center gap-2.5">
97	            <span className={`h-2.5 w-2.5 rounded-full ${server.running ? "bg-emerald-400" : "bg-slate-500"}`} />
98	            <h2 className="text-lg font-semibold text-white">{server.name || server.subdomain}</h2>
99	            <span className="text-xs text-slate-500">{server.running ? "Awake" : "Asleep"}</span>
100	          </div>
101	          <div className="mt-1 flex items-center gap-2">
