146	      {tab === "mods" && <ModsTab server={server} runsPlugins={presets[server.preset]?.kind === "plugins"} />}
147	      {tab === "roles" && <RolesTab presetKind={presets[server.preset]?.kind ?? "properties"} />}
148	      {tab === "settings" && <Settings fields={schemaFields} properties={properties} />}
