153	
154	function PowerButtons({ running }: { running: boolean }) {
155	  const [, startAction, startPending] = useActionState(startFreeMinecraftServer, {});
156	  const [, stopAction, stopPending] = useActionState(stopFreeMinecraftServer, {});
157	  const [, restartAction, restartPending] = useActionState(restartFreeMinecraftServer, {});
158	  const busy = startPending || stopPending || restartPending;
159	  return (
160	    <div className="mt-2 flex justify-end gap-2">
161	      {!running ? (
162	        <form action={startAction}>
163	          <button className="btn-primary text-xs" disabled={busy}>{startPending ? "Starting…" : "Start"}</button>
164	        </form>
165	      ) : (
166	        <>
167	          <form action={restartAction}>
168	            <button className="btn-secondary text-xs" disabled={busy}>{restartPending ? "Restarting…" : "Restart"}</button>
169	          </form>
170	          <form action={stopAction}>
171	            <button className="btn-ghost text-xs" disabled={busy}>{stopPending ? "Stopping…" : "Stop"}</button>
172	          </form>
173	        </>
174	      )}
175	    </div>
176	  );
177	}
178	
179	function Console({ running }: { running: boolean }) {
180	  const [log, setLog] = useState<{ cmd: string; out: string; err?: boolean }[]>([]);
181	  const [pending, startTransition] = useTransition();
182	
183	  function submit(formData: FormData) {
184	    const cmd = String(formData.get("command") ?? "");
185	    if (!cmd.trim()) return;
186	    startTransition(async () => {
187	      const res = await sendFreeMinecraftCommand({}, formData);
188	      setLog((l) => [...l, { cmd, out: res.error ?? res.response ?? "", err: !!res.error }]);
189	    });
190	  }
191	
192	  return (
193	    <div className="card">
194	      <h3 className="font-semibold text-[var(--fg)]">Console</h3>
195	      {!running && (
196	        <p className="mt-1 text-sm text-amber-300">Server is asleep — commands won&apos;t reach it until someone connects.</p>
197	      )}
198	      <div className="mt-3 h-64 overflow-y-auto rounded-lg border border-white/10 bg-black/40 p-3 font-mono text-xs">
199	        {log.length === 0 && <p className="text-slate-600">Command output will appear here.</p>}
